package com.deutteun.archive;
import android.app.job.JobInfo;import android.app.job.JobScheduler;import android.content.*;import android.net.*;import android.os.*;import androidx.work.*;import java.util.concurrent.TimeUnit;
public final class UploadScheduler { private UploadScheduler(){} public static void schedule(Context c,UploadStore.Task t){ if(Build.VERSION.SDK_INT>=34){try{PersistableBundle b=new PersistableBundle();b.putString("id",t.id);JobInfo j=new JobInfo.Builder(t.id.hashCode(),new ComponentName(c,BackgroundUploadJobService.class)).setExtras(b).setRequiredNetwork(new NetworkRequest.Builder().addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET).build()).setEstimatedNetworkBytes(0,t.bytes).setUserInitiated(true).build();if(c.getSystemService(JobScheduler.class).schedule(j)==JobScheduler.RESULT_SUCCESS)return;}catch(SecurityException ignored){}} Constraints x=new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build();WorkManager.getInstance(c).enqueueUniqueWork("upload-"+t.id,ExistingWorkPolicy.KEEP,new OneTimeWorkRequest.Builder(BackgroundUploadWorker.class).setConstraints(x).setInputData(new Data.Builder().putString("id",t.id).build()).setBackoffCriteria(BackoffPolicy.EXPONENTIAL,10,TimeUnit.SECONDS).build());} public static void resumeAll(Context c){UploadStore s=new UploadStore(c);android.database.Cursor x=s.runnable();try{while(x.moveToNext()){UploadStore.Task t=s.get(x.getString(x.getColumnIndexOrThrow("id")));if(t!=null)schedule(c,t);}}finally{x.close();}} public static void cancel(Context c,String id){if(id==null)return;c.getSystemService(JobScheduler.class).cancel(id.hashCode());WorkManager.getInstance(c).cancelUniqueWork("upload-"+id);} }
